models:model.jaffle_shop.orders.query:
query TableMetadata(
  $environmentId: BigInt!
  $database: String!
  $schema: String!
  $identifier: String!
  $after: String
) {
  environment(id: $environmentId) {
    applied {
      models(first: 100, after: $after, filter: { database: $database, schema: $schema, identifier: $identifier }) {
        edges {
          node {
            uniqueId
            name
            description
            database
            schema
            accountId
            projectId
            alias
            catalog { runId runGeneratedAt columns { name description type } }
            tests { name columnName executionInfo { lastRunStatus } }
            executionInfo { executeCompletedAt lastSuccessRunId }
            parents { uniqueId name resourceType }
          }
        }
        pageInfo { hasNextPage endCursor }
      }
    }
  }
}

